import { useState, useCallback, memo } from "react";
import { View, Text, Pressable } from "react-native";

// Đếm số lần render từng dòng để QUAN SÁT chi phí
window.__rows = 0;

const Row = memo(function Row({ id, onPick }) {
  window.__rows += 1;
  return <Pressable testID={"row" + id} onPress={() => onPick(id)}><Text>Dòng {id}</Text></Pressable>;
});

export default function App() {
  const [picked, setPicked] = useState(null);
  const onPick = useCallback((id) => setPicked(id), []);      // tham chiếu hàm ổn định: memo mới có tác dụng
  return (
    <View>
      <Text testID="picked">{String(picked)}</Text>
      {[1, 2, 3].map((id) => <Row key={id} id={id} onPick={onPick} />)}
    </View>
  );
}

