import { useState, useMemo } from "react";
import { View, Text, Pressable } from "react-native";

window.__calc = 0;
const items = [1, 2, 3, 4];

export default function App() {
  const [tick, setTick] = useState(0);
  const total = useMemo(() => {
    window.__calc++;
    return items.reduce((s, x) => s + x, 0);
  }, []);
  return (
    <View>
      <Text testID="total">{total}</Text>
      <Pressable testID="tick" onPress={() => setTick(tick + 1)}><Text>{tick}</Text></Pressable>
    </View>
  );
}
